function mySqrt(x: number): number {
  // Для 0 и 1 корень равен самому числу
  if (x < 2) {
    return x;
  }

  // Ищем наибольшее m, для которого m * m <= x.
  // При x >= 2 корень не больше x / 2
  let lo = 1;
  let hi = Math.floor(x / 2);
  let answer = 1;

  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);

    // Сравниваем mid <= x / mid вместо mid * mid <= x:
    // так произведение не выходит за пределы точности/диапазона
    if (mid <= Math.floor(x / mid)) {
      // mid подходит — запоминаем и пробуем больше
      answer = mid;
      lo = mid + 1;
    } else {
      // mid слишком велик — ищем левее
      hi = mid - 1;
    }
  }

  return answer;
}

// Время: O(log x)
// Память: O(1)
